#include <stdio.h>
long long rev(long long n) {
    long long r = 0;
    while (n > 0) { r = r * 10 + (n % 10); n /= 10; }
    return r;
}
int is_pal(long long n) { return n == rev(n); }
int main() {
    long long val; if (scanf("%lld", &val) != 1) return 0;
    for (int iter = 0; iter < 1000; iter++) {
        if (iter > 0 && is_pal(val)) { printf("%lld\n", val); return 0; }
        val += rev(val);
    }
    printf("%lld\n", val);
    return 0;
}

